import 'package:flutter/material.dart';enum ChatFolder {  all,  personal,  work,  emergency,  archived,}class ChatFolderService {  static const String _boxName = 'chat_folders';  static final Map<ChatFolder, Color> folderColors = {    ChatFolder.all: Color(0xFF6366F1),    ChatFolder.personal: Color(0xFF10B981),    ChatFolder.work: Color(0xFF3B82F6),    ChatFolder.emergency: Color(0xFFEF4444),    ChatFolder.archived: Color(0xFF6B7280),  };  static final Map<ChatFolder, IconData> folderIcons = {    ChatFolder.all: Icons.chat_bubble_outline,    ChatFolder.personal: Icons.people,    ChatFolder.work: Icons.work,    ChatFolder.emergency: Icons.warning,    ChatFolder.archived: Icons.archive_outlined,  };  static String getFolderName(ChatFolder folder) {    switch (folder) {      case ChatFolder.all:        return 'All Chats';      case ChatFolder.personal:        return 'Personal';      case ChatFolder.work:        return 'Work';      case ChatFolder.emergency:        return 'Emergency';      case ChatFolder.archived:        return 'Archived';    }  }  static IconData getFolderIcon(ChatFolder folder) {    return folderIcons[folder] ?? Icons.chat_bubble_outline;  }  static Color getFolderColor(ChatFolder folder) {    return folderColors[folder] ?? Colors.grey;  }}